from pathlib import Path
from lxml import html,etree
from weasyprint import HTML,CSS
import hashlib,json,shutil
w=Path(__file__).resolve().parent;pub=w/'publication/en';pub.mkdir(parents=True,exist_ok=True);src=w/'book/en/full_content.html';doc=html.fromstring(src.read_bytes());main=doc.xpath('//main')[0]
